+    /// Bounds-checked tensor_data: returns nullptr and sets `err` when the tensor's payload
+    /// would extend past the mapped file.  The unchecked form is kept for hot paths where
+    /// the caller has already validated via GgufModel::in_bounds.
+    const uint8_t* tensor_data_checked(const TensorInfo& t, std::string& err) const {
+        const uint64_t bytes = tensor_payload_bytes(t);
+        if (bytes == 0) { err = "unknown type or non-block-aligned shape for " + t.name; return nullptr; }
+        const uint64_t payload = size_ - data_start_;
+        if (t.offset > payload || bytes > payload - t.offset) {
+            err = "tensor " + t.name + " at offset " + std::to_string(t.offset) +
+                  " size " + std::to_string(bytes) + " exceeds payload " + std::to_string(payload);
+            return nullptr;
+        }
+        return base_ + data_start_ + t.offset;
+    }
