+/// Read the cgroup v2 memory.max limit (bytes), or nullopt when unavailable.
+inline std::optional<uint64_t> conversation_cgroup_limit() {
+    std::ifstream f("/sys/fs/cgroup/memory.max");
+    if (!f) return std::nullopt;
+    std::string s;
+    if (!(f >> s)) return std::nullopt;
+    if (s == "max") return std::nullopt;  // unlimited
+    try { return std::stoull(s); } catch (...) { return std::nullopt; }
+}
+
+/// The effective available memory: min(host available, cgroup limit - current usage).
+inline std::optional<uint64_t> conversation_effective_available() {
+    auto host = conversation_available_memory();
+    auto cgroup = conversation_cgroup_limit();
+    if (!cgroup) return host;
+    // current usage from memory.current
